namespace RunnersZ.Logic { public enum GameState { EnCurso, Victoria, Derrota } public sealed class DoorLives { public int Value{get;private set;}=3; public bool Hit(){if(Value>0)Value--;return Value==0;} public void Reset()=>Value=3;} public sealed class GameSession { public GameState State{get;private set;}=GameState.EnCurso; public void Correct(){if(State!=GameState.EnCurso)return;State=GameState.Victoria;}  public void Lose(){if(State==GameState.EnCurso)State=GameState.Derrota;} public void Reset(){State=GameState.EnCurso;}}}